guidance.correct_example:
def load(a_path: str) -> Result[dict]:
    b_continue = True
    result: Result[dict] = INVALID_RESULT
    try:
        data = json.load(open(a_path))
    except FileNotFoundError as e:
        result = Result.failure(f'File not found: {a_path}: {e}')
        b_continue = False
    except json.JSONDecodeError as e:
        result = Result.failure(f'Invalid JSON in {a_path}: {e}')
        b_continue = False
    if b_continue:
        result = Result.success(data)
    return result

